const ep = (o) => ({ badge: BADGE, cues: STING, endLen: 6.2, ...o })
const end = (line, stars) => (x, t, lt) => partyCard(x, t, lt, { line, stars })
const L = (lt, d, who, s) => [lt, d, who, s]
const glasses = (x, P, id) => { const [cx, cy, s] = P.at(id); x.strokeStyle = INK; x.lineWidth = 6; for (const dx of [-0.13, 0.13]) { x.fillStyle = 'rgba(200,230,255,0.35)'; x.fillRect(cx + dx * s - s * 0.09, cy - s * 0.1, s * 0.18, s * 0.12); x.strokeRect(cx + dx * s - s * 0.09, cy - s * 0.1, s * 0.18, s * 0.12) } x.beginPath(); x.moveTo(cx - s * 0.04, cy - s * 0.05); x.lineTo(cx + s * 0.04, cy - s * 0.05); x.stroke() }
const coat = (x, P, id, col = '#2b5fb0') => { const [cx, cy, s] = P.at(id); box(x, cx - s * 0.3, cy + s * 0.2, s * 0.6, s * 0.1, col, 4); box(x, cx + s * 0.12, cy + s * 0.28, s * 0.1, s * 0.2, col, 4); box(x, cx - s * 0.22, cy - s * 0.64, s * 0.44, s * 0.13, col, 4); x.fillStyle = BONE; x.beginPath(); x.arc(cx, cy - s * 0.68, s * 0.06, 0, Math.PI * 2); x.fill() }
const stand = (x, cx, base, name, col = '#ff8fb1') => { box(x, cx - 200, base - 280, 400, 280, '#f4efe4', 7); box(x, cx - 240, base - 360, 480, 70, col, 6); txt(x, name, cx, base - 324, { size: 44, col: INK }); for (let k = 0; k < 5; k++) { x.fillStyle = k % 2 ? '#ffd36b' : col; x.fillRect(cx - 200 + k * 80, base - 290, 80, 24) } }

